import { EmbedBuilder } from 'discord.js'
import { isFinished } from './meson.js'

// =============================================================================
//   Shared helpers
// =============================================================================

/** Embed side-bar colours. */
const COLOR = {
  ok: 0x1fa97f,       // done (also: wallet with no unfinished swaps)
  pending: 0xe0a324,  // still moving (also: wallet with unfinished swaps)
  bad: 0xd94f4f,      // failed / expired / unlocked / cancelled, not-found
}

/** Discord renders <t:unix:f> in the reader's own timezone. */
const ts = (date, style = 'f') => (date ? `<t:${Math.floor(date.getTime() / 1000)}:${style}>` : '—')

/** Inline-code a value (or an em dash if empty). */
const code = (v) => (v ? `\`${v}\`` : '—')

/** Inline-code values, comma separated; past `max` the rest are only counted, so a long paste cannot push a message over Discord's length limit. */
function codeList (values, max = 5) {
  const shown = values.slice(0, max).map(code).join(', ')
  return values.length > max ? `${shown} and ${values.length - max} more` : shown
}

/** Embed colour for a status: red if not ok, green if done, amber while moving. */
function statusColor (status) {
  if (!status.ok) return COLOR.bad
  return status.done ? COLOR.ok : COLOR.pending
}

// =============================================================================
//   Swap details embed
// =============================================================================

/** "Solana" + address, as one embed field value (amount and token are in the Amount field). */
function sideValue (side) {
  const lines = [`**${side.chain}**`]
  if (side.address) {
    lines.push(side.addressUrl ? `[${side.address}](${side.addressUrl})` : code(side.address))
  }
  return lines.join('\n')
}

/** Discord's limit on one embed field's value. */
const FIELD_MAX = 1024

/** The order steps are listed in the transaction hashes field; any other step goes last, in API order. */
const STEP_ORDER = ['posted', 'bonded', 'locked', 'executed', 'requesting', 'releasing', 'released', 'unlocked', 'cancelled']

/**
 * One entry per step (posted, bonded, …) for the transaction hashes field: its successful transaction, or — while it has only failed — its latest attempt, with no mention of the failures.
 * Failed retries are not listed, so a release retried many times cannot push the successful hash out of the field; every attempt is still on the Meson explorer.
 * The API lists events in no reliable order (CANCELLED before EXECUTED has been seen) and without timestamps, so steps are sorted by STEP_ORDER; among a step's failed attempts the last listed is taken as the latest.
 */
function txSteps (events) {
  const steps = new Map()
  for (const e of events) {
    const step = String(e.name).split(':')[0].toLowerCase()
    if (!steps.has(step)) steps.set(step, { step, ok: null, failed: [] })
    const s = steps.get(step)
    if (String(e.name).toUpperCase().includes('FAILED')) s.failed.push(e)
    else s.ok = e
  }
  const rank = (s) => (STEP_ORDER.includes(s.step) ? STEP_ORDER.indexOf(s.step) : STEP_ORDER.length)
  return [...steps.values()].sort((a, b) => rank(a) - rank(b))
}

/**
 * The source-side and destination-side transaction hashes, with links. Trimmed by whole steps to fit a field — a raw character cut could split a link.
 *
 * The release is one entry that moves releasing → releasing (confirming) → released: the hashless RELEASING request until a release transaction exists, then that transaction, called "released" only once it has confirmed.
 */
function txValue (swap) {
  if (!swap.events.length) return '_no on-chain transactions yet_'
  const finished = isFinished(swap.status)
  const steps = txSteps(swap.events)
  const hasRelease = steps.some((s) => s.step === 'released')
  let out = ''
  for (const s of steps) {
    if (s.step === 'releasing' && hasRelease) continue
    const e = s.ok ?? s.failed.at(-1)
    // Some events carry no hash yet (e.g. REQUESTING, RELEASING: asked for, not on-chain) — once the swap is finished none will come, so they are left out.
    if (!e.hash && finished) continue
    // A release still confirming, or only failed so far (being retried), is not "released" yet.
    const name = s.step === 'released' && !(s.ok && !s.ok.pending) ? 'releasing' : s.step
    const link = !e.hash ? '_no transaction yet_' : e.url ? `[${e.hash}](${e.url})` : code(e.hash)
    const entry = `**${name}**${e.pending ? ' (confirming)' : ''}\n${link}`
    const next = out ? `${out}\n${entry}` : entry
    if (next.length > FIELD_MAX - 2) return `${out}\n…`
    out = next
  }
  return out || '_no on-chain transactions yet_'
}

/**
 * The swap details embed — posted in tickets and by /meson-query.
 * @param {Awaited<ReturnType<import('./meson.js').lookupSwap>>} swap
 * @param {{requestedBy?: string, sourceNote?: string, serial?: number|null}} [opts] `serial` numbers the embed ("Meson swap #2") when a ticket has several swaps.
 */
export function buildSwapEmbed (swap, opts = {}) {
  const s = swap.status
  const embed = new EmbedBuilder()
    .setColor(statusColor(s))
    .setTitle(`Meson swap${opts.serial ? ` #${opts.serial}` : ''} — ${s.label}${s.star}`)
    .setURL(swap.explorerUrl)
    .setDescription(s.detail ? `${s.detail.charAt(0).toUpperCase()}${s.detail.slice(1)}` : null)
    .addFields(
      { name: 'From', value: sideValue(swap.from), inline: true },
      { name: 'To', value: sideValue(swap.to), inline: true },
      { name: 'Amount', value: `${swap.from.amount} ${swap.from.token} → ${swap.to.amount} ${swap.to.token}` },
      { name: 'Transaction hashes', value: txValue(swap) },
    )

  embed.addFields({ name: 'Timing', value: `Requested ${ts(swap.requestedAt)}` })

  embed.addFields({ name: 'Explorer link', value: swap.explorerUrl })

  const footer = [opts.sourceNote, opts.requestedBy ? `requested by ${opts.requestedBy}` : null]
    .filter(Boolean)
    .join(' · ')
  embed.setFooter({ text: footer || 'Meson Explorer' })

  return embed
}

// =============================================================================
//   Plain-text messages
// =============================================================================

/**
 * Plain-text reply to a new swap's details while it is still moving normally (status.ok, not finished).
 * `serial` matches the "#n" on the details embed when a ticket has several swaps, as on the closing message.
 */
export function buildProcessingMessage ({ serial = null } = {}) {
  return `⏳ ${serial ? `**Swap #${serial}** · ` : ''}Your transaction is currently being processed, please wait patiently. ` +
    'We confirm that your assets are safe and the transaction will be completed shortly.'
}

/** Private reply to /meson-query used outside the REPLY_CATEGORY_IDS categories. */
export const QUERY_WRONG_CHANNEL_MESSAGE = '🚫 `/meson-query` can only be used in support ticket channels.'

/** Last line of a closing message once every swap in the ticket is finished. */
export const CLOSING_SOON =
  '-# This ticket will be closed soon. If you still need help, our support team will respond to your message at the earliest or within 3-12hrs.'

/**
 * The closing note posted (as plain text, not an embed) as a reply to the swap details once a swap has finished (Done / Released → ✅, Cancelled → ↩️), or null if it has not.
 *
 * @param {{serial?: number|null, closingSoon?: boolean}} [opts] `serial` matches the "#n" on the details embed when a ticket has several swaps; `closingSoon` (default true) is false while other swaps in the ticket are still open, so we do not promise the ticket is about to close.
 */
export function buildOutcomeMessage (swap, { serial = null, closingSoon = true } = {}) {
  const tag = serial ? ` — Swap #${serial}` : ''
  const footer = closingSoon ? CLOSING_SOON : null
  // Released (before the LP executed) is as complete as Done for the user.
  if (swap.status.label === 'Done' || swap.status.label === 'Released') {
    return [
      `**✅ Transaction Completed${tag}**`,
      '',
      'Your transaction has been completed. Please check your **receiving address** for the funds.',
      footer,
    ].filter((l) => l !== null).join('\n')
  }
  if (swap.status.label === 'Cancelled') {
    return [
      `**↩️ Transaction Cancelled${tag}**`,
      '',
      'Your transaction has been cancelled and the funds have been returned to your **sending address**.',
      footer,
    ].filter((l) => l !== null).join('\n')
  }
  return null
}

/** Plain-text reply when a user pastes swap-shaped text that Meson does not know. */
export function buildSwapNotFoundMessage (queries) {
  return [
    `❓ I couldn't find a Meson swap for ${codeList(queries)}.`,
    'Please double-check the **swap ID**, **transaction hash** or **explorer link**. ' +
      'A swap can take a moment to appear right after it is submitted.',
  ].join('\n')
}

// =============================================================================
//   Wallet embeds
// =============================================================================

/** Status icon on each row of the wallet list (finished swaps are never listed); any status not here — Requesting, Posted, Bonded, Locked — gets ⚪. */
const STATUS_EMOJI = {
  Releasing: '🟡',
  Pending: '⚪',
  Failed: '🔴',
  Expired: '🔴',
  Unlocked: '🔴',
}

/**
 * One row of an address's swap list: link, route, amount, request time.
 * Only the request time is shown, as on the details embed — no expiry, no "took X".
 */
function addressRowValue (swap) {
  const lines = [
    `[${swap.swapId}](${swap.explorerUrl})`,
    `${swap.from.chain} → ${swap.to.chain} · ${swap.from.amount} ${swap.from.token} → ${swap.to.amount} ${swap.to.token}`,
    `Requested ${ts(swap.requestedAt)}`,
  ]
  return lines.join('\n')
}

/**
 * Rows per embed: ~300 chars each, so 10 keeps an embed well under Discord's 6000-character cap (which applies to all of a message's embeds combined).
 */
const ROWS_PER_EMBED = 10

/**
 * Posted by ticket auto-detect when the ticket has a wallet address but no swap ID or hash: only that wallet's swaps that are not finished (Done, Released or Cancelled), so a long history of fine past swaps does not bury the one that is actually the problem.
 * Every unfinished swap is listed — over several embeds (send one per message) if there are more than ROWS_PER_EMBED.
 *
 * @param {string} address
 * @param {Awaited<ReturnType<import('./meson.js').listUnfinishedSwapsForAddress>>} result
 * @param {{sourceNote?: string, missed?: string[]}} [opts] `missed`: IDs the user pasted that did not resolve, which is why the wallet is shown instead
 * @returns {EmbedBuilder[]}
 */
export function buildUnfinishedAddressEmbeds (address, result, opts = {}) {
  const { swaps, scanned, since, stoppedBy } = result
  const chunks = []
  for (let i = 0; i < swaps.length; i += ROWS_PER_EMBED) chunks.push(swaps.slice(i, i + ROWS_PER_EMBED))
  if (!chunks.length) chunks.push([])

  const embeds = chunks.map((rows, i) => {
    const embed = new EmbedBuilder()
      .setColor(swaps.length ? COLOR.pending : COLOR.ok)
      .setTitle(!swaps.length
        ? 'No unfinished swaps for this wallet'
        : chunks.length === 1
          ? `Unfinished swaps for this wallet: ${swaps.length}`
          // Split over several messages — a running count, so the last reads "13 out of 13".
          : `Unfinished swaps for this wallet: ${i * ROWS_PER_EMBED + rows.length} out of ${swaps.length}`)
      .setURL(`https://explorer.meson.fi/address/${address}`)
    if (i === 0) {
      // The wallet is a fallback — say why it is being shown instead of a swap.
      const missed = opts.missed?.length
        ? `\n\nCould not find a swap for ${codeList(opts.missed)}, so here are this wallet's unfinished swaps instead.`
        : ''
      embed.setDescription(`${code(address)}${missed}`)
    }
    for (const swap of rows) {
      const emoji = STATUS_EMOJI[swap.status.label] ?? '⚪'
      embed.addFields({ name: `${emoji} ${swap.status.label}${swap.status.star}`, value: addressRowValue(swap) })
    }
    return embed
  })
  const embed = embeds[embeds.length - 1] // the closing note goes on the last one

  // Say how far back we looked, so "none" is not read as "never had a problem".
  const scope = stoppedBy === 'end'
    ? `all ${scanned} swap(s) this wallet has ever made`
    : stoppedBy === 'age'
      ? `${scanned} swap(s) since ${ts(since, 'D')}`
      : `the ${scanned} most recent swap(s) — older ones were not checked`
  embed.addFields({ name: 'Checked', value: `${scope}. Completed and cancelled swaps are not listed.` })

  const footer = [opts.sourceNote].filter(Boolean).join(' · ')
  embed.setFooter({ text: footer || 'Meson Explorer' })
  return embeds
}

// =============================================================================
//   Not-found embed
// =============================================================================

/** Shown when nothing lookupable was found or the swap does not exist. */
export function buildNotFoundEmbed (query, { hint } = {}) {
  return new EmbedBuilder()
    .setColor(COLOR.bad)
    .setTitle('No Meson swap found')
    .setDescription(
      (query ? `I could not find a swap for ${code(query)}.\n\n` : '') +
      (hint ??
        'Please paste one of:\n' +
        '• the **swap ID** (`0x` + 64 characters)\n' +
        '• the **transaction hash** from either chain\n' +
        '• the **Meson explorer link** for the swap\n\n' +
        'A swap can also take a moment to appear right after it is submitted.')
    )
}

// =============================================================================
//   Recognising our own messages
// =============================================================================

// Restart recovery (recover.js) rebuilds a ticket from the messages above, so these must change together with the builders: a message they no longer recognise is not recovered.

/** The swap ID of a swap details embed (buildSwapEmbed: title "Meson swap …", URL = the swap's explorer link), or null for any other embed. Its "#n" is its posting order, not read back. */
export function readSwapEmbed (embed) {
  const id = embed?.title?.startsWith('Meson swap') && embed.url?.match(/\/swap\/(0x[0-9a-fA-F]{64})$/)
  return id ? { swapId: id[1].toLowerCase() } : null
}

/** The wallet address of a wallet embed (buildUnfinishedAddressEmbeds: URL = the address's explorer page), or null. */
export const readWalletEmbed = (embed) => embed?.url?.match(/explorer\.meson\.fi\/address\/([^/?#]+)$/)?.[1] ?? null

/** Which follow-up a plain-text message is: ⏳ (buildProcessingMessage) or ✅ / ↩️ (buildOutcomeMessage) — or null. */
export function followUpKind (content = '') {
  if (content.startsWith('⏳')) return 'processing'
  if (content.startsWith('**✅') || content.startsWith('**↩️')) return 'outcome'
  return null
}
